def aplicar_descuentos(precio, descuentos):
    original = precio
    try:
        for d in descuentos:
            if not 0 <= d <= 50:
                raise ValueError("descuento fuera de rango")
            precio = precio * (100 - d) / 100
    except ValueError:
        return original
    return round(precio, 2)

aplicar_descuentos(100, [10, 80])  # 100

